test('official all-row BAF Draft rejection permits a lineage-bound proven transport for the SAME intents without rewriting original CSV',()=>fixture(async(root,keys)=>{const f=await rejectedFullTemplate(root,keys),state=await readV2State(root),originalPath=f.job.csvPath!,original=await fs.readFile(path.join(root,originalPath)),groups=structuredClone(f.job.groups);assert.equal(f.job.stage,'uncertain');assert.equal(f.job.rejectedDraftAction?.errorCode,'BAF.Error.5');const result=await recoverV2RejectedDraftAction(root,f.job.id,f.job.lease,f.packet);assert.equal(result.job.stage,'ready-upload');assert.equal(result.job.id,f.job.id);assert.deepEqual(result.job.groups,groups);assert.equal(result.job.csvContract,undefined);assert.ok(result.job.csvPath?.includes('-transport-recovery-'));assert.ok((await fs.readFile(path.join(root,result.job.csvPath!),'utf8')).startsWith('#INFO,Version=0.0.2'));assert.deepEqual(await fs.readFile(path.join(root,originalPath)),original);assert.deepEqual(await readV2State(root),state);assert.deepEqual((await readV2BrowserJob(root,f.job.id)).transportRecovery?.previousCsv,{path:originalPath,sha256:f.job.csvSha256});assert.equal((await recoverV2RejectedDraftAction(root,f.job.id,f.job.lease,f.packet)).replayed,true);const handoff=await beginV2BrowserUpload(root,f.job.id,f.job.lease);assert.equal(handoff.absoluteCsvPath,path.join(root,result.job.csvPath!));await assert.rejects(recoverV2RejectedDraftAction(root,f.job.id,f.job.lease,f.packet),/already started/);assert.deepEqual(await fs.readFile(path.join(root,originalPath)),original);},2,true));
test('missing, mixed, uncertain or different official failures never permit transport recovery',()=>fixture(async(root,keys)=>{const f=await rejectedFullTemplate(root,keys,'1,,unknown,FAILED,,OTHER.Error,Wrong error');assert.equal(f.job.rejectedDraftAction,undefined);const before=await fs.readFile(path.join(root,'artifacts/card-processing-v2/browser-jobs',f.job.id+'.json'));await assert.rejects(recoverV2RejectedDraftAction(root,f.job.id,f.job.lease,f.packet),/all-row full-template rejection/);assert.deepEqual(await fs.readFile(path.join(root,'artifacts/card-processing-v2/browser-jobs',f.job.id+'.json')),before);},2,true));
test('recovery requires fresh unchanged official report, exact unimported intent and captured permission',()=>fixture(async(root,keys)=>{const f=await rejectedFullTemplate(root,keys),state=await readV2State(root);await assert.rejects(recoverV2RejectedDraftAction(root,f.job.id,{owner:'foreign',token:'0'.repeat(64)},f.packet),/Exact browser bridge lease/);const q=JSON.parse(await fs.readFile(f.queueFile,'utf8')),originalQ=JSON.stringify(q);q.instructions.push({id:'revoked',supersedes:[f.packet.instructionId]});await fs.writeFile(f.queueFile,JSON.stringify(q));await assert.rejects(recoverV2RejectedDraftAction(root,f.job.id,f.job.lease,f.packet),/recovery authority/);await fs.writeFile(f.queueFile,originalQ);const report=path.join(root,f.receipt.report.path),bytes=await fs.readFile(report);await fs.appendFile(report,'changed');await assert.rejects(recoverV2RejectedDraftAction(root,f.job.id,f.job.lease,f.packet),/hash mismatch/);await fs.writeFile(report,bytes);await withV2State(s=>{s.submissions[keys[0]].status='uncertain';},root);await assert.rejects(recoverV2RejectedDraftAction(root,f.job.id,f.job.lease,f.packet),/unimported intents/);const after=await readV2State(root);assert.equal(Object.keys(after.submissions).length,Object.keys(state.submissions).length);assert.equal(after.cards['V2-1'].draftId,undefined);assert.equal((await readV2BrowserJob(root,f.job.id)).stage,'uncertain');},1,true));


test('known full-FX metadata line offset is accepted ONLY for complete exact-SKU zero-ID BAF failure rows',()=>fixture(async(root,keys)=>{const f=await rejectedFullTemplate(root,keys),input=assertV2DraftOnlyCsv(await fs.readFile(path.join(root,f.job.csvPath!),'utf8')),bindings=f.job.groups.map((g,n)=>({key:g.key!,sku:g.payload.sku,captureIds:g.payload.captureIds,lineNumber:input.rows[n].lineNumber})),header='Line Number,Action,Status,ErrorCode,ErrorMessage,ItemID,ReferenceID,CustomLabel,DraftID',rows=f.job.groups.map((g,n)=>`${input.rows[n].lineNumber-1},Draft,Failure,BAF.Error.5,Unable to find Task Action Id for task Draft,,,${g.payload.sku},`),text=[header,...rows].join('\n')+'\n';assert.equal(parseV2RejectedFullTemplateDraftActionReport(text,bindings).length,2);for(const changed of [text.replace('Failure','Success'),text.replace(',,V2-',',123,V2-'),text.replace('BAF.Error.5','OTHER.Error'),text.replace(rows[0],rows[0].replace(/^2,/, '1,')),text.replace(f.job.groups[1].payload.sku,f.job.groups[0].payload.sku)])assert.throws(()=>parseV2RejectedFullTemplateDraftActionReport(changed,bindings));const relative='artifacts/full-fx-offset-result.csv';await fs.writeFile(path.join(root,relative),text);const receipt={...f.receipt,report:{path:relative,sha256:createHash('sha256').update(text).digest('hex')}};const recorded=await recordV2BrowserUpload(root,f.job.id,f.job.lease,receipt);assert.equal(recorded.job.rejectedDraftAction?.jobId,receipt.jobId);assert.equal(recorded.rows.every(row=>row.status==='failed'&&!row.draftId),true);const recovered=await recoverV2RejectedDraftAction(root,f.job.id,f.job.lease,f.packet);assert.equal(recovered.job.stage,'ready-upload');assert.equal(recovered.job.groups.length,2);},2,true));
